                ["K", 91, 100, 80],
                ["L", 82, 100, 120],
                ["M", 73, 100, 80],
            ],
            "top": 3,
        }
        result = call_candidate("components/market_ranking/work.py", "compute", args=[payload])
        self.assertEqual(result, ["J", "K", "L"])

    def test_window_excludes_old_events(self):
        # L = 100, window 71..100. Event at day 70 excluded.
        payload = {
            "market": [
